{"command":"$ProgressPreference='SilentlyContinue'
$results = @()
foreach ($p in @('/', '/mcp', '/sse', '/messages')) {
  try {
    $r = Invoke-WebRequest -Uri "http://127.0.0.1:12463$p" -Method GET -TimeoutSec 3 -UseBasicParsing
    $results += [pscustomobject]@{Path=$p; Status=[int]$r.StatusCode; ContentType=$r.Headers['Content-Type']; Body=($r.Content.Substring(0, [Math]::Min(300, $r.Content.Length)))}
  } catch {
    $results += [pscustomobject]@{Path=$p; Status='ERR'; ContentType=''; Body=$_.Exception.Message}
  }
}
$results | Format-List","timeout_ms":20000}

